// CLX B2C v2.1 - Build Smart Scan List
//
// Inputs:
//   Fetch Active Clients -> clients where active = true
//   Fetch Scan Tracker   -> scan_query_tracker, THE query registry
//
// WHAT CHANGED AND WHY
//
// The queries, the cities and the industry labels used to be three
// hardcoded objects in this node. Adding a city meant editing JavaScript
// and redeploying a workflow; onboarding Eazer meant a code change before
// a single search could run. Configuration that lives in code is not
// configuration, it is a release.
//
// scan_query_tracker already held every (query, city, industry,
// product_type) combination the engine had ever run, plus paused and
// last_scanned_at. It was being used as a memo of what had happened. It is
// now the source of what should happen -- the same rows, read forwards.
//
// So the whole registry is data:
//   add a search      INSERT one row
//   add a city        INSERT the rows for that city
//   stop a search     UPDATE ... SET paused = true, or DELETE the row
//   onboard a vertical INSERT its rows and set a client's product_type
//
// No deploy, no code review, no downtime.
//
// FAILS CLOSED. The previous version, finding no client that matched a
// template, scanned EVERY hardcoded industry -- a misconfiguration
// silently became the widest possible spend. An active product_type with
// no rows is now reported by name and scanned not at all.

const WEEKLY_RETRY_MS = 7 * 24 * 60 * 60 * 1000;

function readItems(nodeName) {
  try {
    const items = $(nodeName).all();
    if (!items || items.length === 0) return [];
    const first = items[0].json || {};
    if (Array.isArray(first.body)) return first.body;
    return items.map(i => i.json).filter(x => x && typeof x === 'object');
  } catch (e) {
    console.log('[CLX v2.1] readItems(' + nodeName + ') error: ' + e.message);
    return [];
  }
}

const clients = readItems('Fetch Active Clients');
const registry = readItems('Fetch Scan Tracker');

console.log('[CLX v2.1] Active clients: ' + clients.length);
console.log('[CLX v2.1] Registry rows:  ' + registry.length);

// ---- 1. Which product types are in play? ------------------------------
// A client declares its product_type. Older rows only carry an industry
// label, so that is matched against the registry's own industry column
// rather than against a hardcoded lookup table.
const industryToType = {};
for (const r of registry) {
  if (r && r.industry && r.product_type) {
    industryToType[String(r.industry).toLowerCase()] = r.product_type;
  }
}

const activeProductTypes = new Set();
for (const c of clients) {
  if (!c) continue;
  if (c.product_type) {
    activeProductTypes.add(c.product_type);
  } else if (c.industry && industryToType[String(c.industry).toLowerCase()]) {
    activeProductTypes.add(industryToType[String(c.industry).toLowerCase()]);
  }
}

if (activeProductTypes.size === 0) {
  console.log('[CLX v2.1] No active client declares a product_type. Nothing to scan.');
  return [];
}
console.log('[CLX v2.1] Active product types: ' +
            Array.from(activeProductTypes).join(', '));

// ---- 2. Candidates are registry rows, not generated strings -----------
const candidates = [];
const seen = new Set();
const covered = new Set();

for (const r of registry) {
  if (!r || !r.search_query || !r.city || !r.product_type) continue;
  if (!activeProductTypes.has(r.product_type)) continue;
  covered.add(r.product_type);
  const key = r.search_query + '||' + r.city;
  if (seen.has(key)) continue;
  seen.add(key);
  candidates.push({
    city: r.city,
    industry: r.industry || r.product_type,
    product_type: r.product_type,
    search_query: r.search_query,
    _paused: r.paused === true,
    _last: r.last_scanned_at || null
  });
}

// A client with no searches is a configuration mistake, and it is the kind
// that hides: the run succeeds, finds nothing, and looks like a quiet day.
for (const pt of activeProductTypes) {
  if (!covered.has(pt)) {
    console.log('[CLX v2.1] WARNING: product_type "' + pt + '" has an active ' +
                'client but NO rows in scan_query_tracker. Nothing will be ' +
                'searched for it. Seed its queries to switch it on.');
  }
}

// ---- 3. Smart-scan filter (unchanged behaviour) -----------------------
const now = Date.now();
const scanList = [];
let skippedPaused = 0, scheduledRetry = 0, active = 0;

for (const c of candidates) {
  if (!c._paused) {
    active++;
    scanList.push(c);
    continue;
  }
  const lastMs = c._last ? Date.parse(c._last) : 0;
  if (!lastMs || (now - lastMs) >= WEEKLY_RETRY_MS) {
    scheduledRetry++;
    scanList.push(c);
    continue;
  }
  skippedPaused++;
}

console.log('[CLX v2.1] Scan plan - candidates: ' + candidates.length
          + ' | active: ' + active
          + ' | weekly-retry: ' + scheduledRetry
          + ' | skipped(paused<7d): ' + skippedPaused
          + ' | TOTAL TO SCAN: ' + scanList.length);

if (scanList.length === 0) {
  console.log('[CLX v2.1] Nothing to scan - every query paused and inside ' +
              'its retry window.');
}

return scanList.map(function (item) {
  return { json: {
    city: item.city,
    industry: item.industry,
    product_type: item.product_type,
    search_query: item.search_query
  } };
});

// CLX B2C v2.1 — Handle Maps Error
const ctx = $('Split In Batches').item.json;
const raw = $input.item.json || {};

const httpError = raw.error || raw.errorMessage || null;
const statusCode = raw.statusCode || (raw.headers && raw.headers.status) || null;

const body = raw.body || raw;
const googleError = body && body.error && (body.error.message || body.error.status) ? body.error : null;

const httpFailed = (typeof statusCode === 'number' && statusCode >= 400);
const hasError = Boolean(httpError || googleError || httpFailed);

if (hasError) {
  const code = googleError ? String(googleError.code || googleError.status || 'google_error')
             : httpFailed ? String(statusCode)
             : 'unknown';
  const message = googleError ? (googleError.message || googleError.status || 'Google Places error')
                : httpError ? String(httpError)
                : 'HTTP ' + statusCode;
  console.log('[CLX v2.1] Maps error for "' + ctx.search_query + '": ' + message);
  return {
    json: {
      has_error: true,
      error_code: code,
      error_message: message,
      input_data: ctx,
      ...ctx
    }
  };
}

return {
  json: {
    has_error: false,
    ...ctx,
    places: (body && body.places) || []
  }
};

// CLX B2C v2.1 — Parse Places Results
const data = $input.item.json || {};
const ctx = $('Split In Batches').item.json;
const places = Array.isArray(data.places) ? data.places : [];

if (places.length === 0) {
  return { json: { businesses: [], count: 0, results_found: 0, ...ctx } };
}

const businesses = [];
const seen = {};

for (const place of places) {
  const name = (place.displayName && place.displayName.text) ? place.displayName.text : '';
  if (!name) continue;
  const key = name.toLowerCase();
  if (seen[key]) continue;
  seen[key] = true;

  businesses.push({
    name: name,
    formatted_address: place.formattedAddress || '',
    phone: place.nationalPhoneNumber || '',
    website: place.websiteUri || '',
    place_id: place.id || '',
    city: ctx.city,
    industry: ctx.industry,
    product_type: ctx.product_type,
    search_query: ctx.search_query
  });
}

console.log('[CLX v2.1] Parsed ' + businesses.length + ' businesses for query: ' + ctx.search_query);

return {
  json: {
    businesses: businesses,
    count: businesses.length,
    results_found: businesses.length,
    ...ctx
  }
};

// CLX B2C v2.1 — No Results path
// Emits a tracker-ready payload with new_leads=0 so Update Scan Tracker
// can record this query as a zero-result scan.
const ctx = $input.item.json || {};
return {
  json: {
    _tracker: {
      p_search_query: ctx.search_query,
      p_city:         ctx.city,
      p_industry:     ctx.industry,
      p_product_type: ctx.product_type,
      p_new_leads:    0
    }
  }
};

// CLX B2C v2.1 — Process Each Business
const data = $('Parse Places Results').item.json;
const businesses = data.businesses || [];
if (businesses.length === 0) return [];

return businesses.map(biz => ({
  json: {
    p_full_name: null,
    p_email: null,
    p_phone: biz.phone || null,
    p_company: biz.name,
    p_job_title: 'Owner',
    p_industry: biz.industry,
    p_city: biz.city,
    p_source: 'google_maps_discovery',
    p_lead_status: 'New Lead',
    p_product_type: biz.product_type,
    p_notes: 'Places ID: ' + (biz.place_id || '') + ' | Address: ' + (biz.formatted_address || '') + (biz.website ? ' | Website: ' + biz.website : ''),
    _scan_city: biz.city,
    _scan_query: biz.search_query,
    _scan_industry: biz.industry,
    _scan_product_type: biz.product_type
  }
}));

// CLX B2C v2.1 — Parse RPC Response
const input = $input.item.json || {};
const ctx = $('Process Each Business').item.json || {};
const company = ctx.p_company || 'unknown';

const httpErr = input.error || input.errorMessage || null;
const statusCode = typeof input.statusCode === 'number' ? input.statusCode : null;
const httpFailed = httpErr || (statusCode !== null && statusCode >= 400);

if (httpFailed) {
  const message = httpErr ? String(httpErr) : ('HTTP ' + statusCode);
  console.log('[CLX v2.1] RPC failure for ' + company + ': ' + message);
  return {
    json: {
      status: 'error',
      error_code: httpErr ? 'rpc_error' : String(statusCode),
      error_message: message,
      company: company,
      client_id: null,
      client_matched: false,
      _scan_city: ctx._scan_city,
      _scan_query: ctx._scan_query,
      _scan_industry: ctx._scan_industry,
      _scan_product_type: ctx._scan_product_type
    }
  };
}

const body = input.body !== undefined ? input.body : input;
let rec = null;
if (Array.isArray(body)) rec = body[0] || null;
else if (body && typeof body === 'object') rec = body;

const status = rec && rec.status ? String(rec.status).toLowerCase() : 'unknown';
const id = rec && rec.id ? rec.id : null;
const client_id = rec && rec.client_id ? rec.client_id : null;
const client_matched = rec && rec.client_matched === true;

console.log('[CLX v2.1] RPC ' + status + ' for ' + company
          + (id ? ' (id=' + id + ')' : '')
          + (client_id ? ' → client=' + client_id : ' → unassigned'));

return {
  json: {
    status: status,
    id: id,
    company: company,
    client_id: client_id,
    client_matched: client_matched,
    _scan_city: ctx._scan_city,
    _scan_query: ctx._scan_query,
    _scan_industry: ctx._scan_industry,
    _scan_product_type: ctx._scan_product_type
  }
};

// CLX B2C v2.1 — Prep Tracker (Inserted branch)
// Builds the upsert_scan_tracker payload for a successful insert.
const ctx = $('Parse RPC Response').item.json || {};
return {
  json: {
    _tracker: {
      p_search_query: ctx._scan_query,
      p_city:         ctx._scan_city,
      p_industry:     ctx._scan_industry,
      p_product_type: ctx._scan_product_type,
      p_new_leads:    1
    }
  }
};

// CLX B2C v2.1 — Prep Tracker (Duplicate / Error branch)
// Emits an upsert_scan_tracker payload with new_leads=0 so the
// tracker counts this as a non-productive outcome.
const ctx = $('Parse RPC Response').item.json || {};
return {
  json: {
    _tracker: {
      p_search_query: ctx._scan_query,
      p_city:         ctx._scan_city,
      p_industry:     ctx._scan_industry,
      p_product_type: ctx._scan_product_type,
      p_new_leads:    0
    }
  }
};

// CLX B2C v2.1 — Scan Complete Summary
const resp = $('Fetch Today Scan Log').item.json || {};
const body = resp.body !== undefined ? resp.body : resp;
const rows = Array.isArray(body) ? body : [];

let results = 0, inserted = 0, duplicates = 0, errors = 0;
for (const r of rows) {
  results    += Number(r.results_found       || 0);
  inserted   += Number(r.new_leads_inserted  || 0);
  duplicates += Number(r.duplicates_skipped  || 0);
  errors     += Number(r.errors              || 0);
}

const summary = {
  workflow: 'CLX-B2C-Discovery',
  version: 'v2.1',
  run_completed_at: new Date().toISOString(),
  scan_log_rows: rows.length,
  totals: {
    results_found: results,
    new_leads_inserted: inserted,
    duplicates_skipped: duplicates,
    errors: errors
  },
  estimated_api_spend_usd: Number((rows.length * 0.032).toFixed(2)),
  message: '[CLX v2.1] Daily scan complete — ' + inserted + ' new leads, ' + duplicates + ' duplicates, ' + errors + ' errors across ' + rows.length + ' logged batches.'
};

console.log(summary.message);
return { json: summary };

// Tenant-scoped discovery entry. Fails closed.
//
// A tenant-originated discovery job without an owning client is refused
// rather than quietly writing to the house pool -- an unowned lead in a
// customer's workspace is worse than no lead, and the house pool is not
// customer inventory.

const body = ($input.item.json && $input.item.json.body) || $input.item.json || {};
const secret = body.internal_secret || '';
const expected = $env.INTERNAL_EMAIL_SECRET || '';

// Two different failures, told apart. An opaque 401 cannot distinguish
// "you sent the wrong secret" from "this server has no secret configured,
// so nobody can ever authenticate" -- and 60 workflows depend on this one
// variable. Reporting the unconfigured case discloses nothing usable: when
// it is unset, fail-closed means no caller gets in either way, so this
// leaks a configuration state, never a credential.
if (!expected) {
  return { json: { _reject: true, status: 503,
    error: 'internal_secret_not_configured',
    hint: 'INTERNAL_EMAIL_SECRET is not set in the n8n container environment. No caller can authenticate until it is.' } };
}
if (secret !== expected) {
  return { json: { _reject: true, status: 401, error: 'internal secret required' } };
}

const clientId = body.client_id || null;
if (!clientId) {
  return { json: {
    _reject: true, status: 400, error: 'client_id required',
    hint: 'Tenant discovery must name its owner. Use the schedule trigger for the Crystallux house pool.'
  } };
}

const uuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
if (!uuid.test(String(clientId))) {
  return { json: { _reject: true, status: 400, error: 'client_id is not a uuid' } };
}

return { json: {
  _reject: false,
  _tenant_scoped: true,
  client_id: clientId,
  vertical: body.vertical || null,
  city: body.city || null,
  requested_by: body.requested_by || null,
  correlation_id: body.correlation_id || null,
  requested_at: new Date().toISOString()
} };
